export const records=[['הניסוי הראשון','ניסינו לייצר קורי משי חזקים לחילוץ אנשים ממבנים שקרסו. בתחילה העכביש היה קטן והתוצאות נראו מבטיחות.'],['על קירות התא','המשי התחזק, אבל גם העכביש גדל. הוא טיפס על הקירות, והחיישנים שבתקרה הפסיקו להגיב.'],['התא נפרץ','מערכת הבקרה המשיכה להזין את הניסוי אחרי פקודת העצירה. כשהצוות חזר, הזכוכית הייתה שבורה והתא ריק.'],['השוטרים הגיעו','צוות החילוץ והשוטרים סרקו את הבית. הם מצאו קורים בכל יציאה. הפנס של האחרון בקבוצה כבה; הקשר נקטע.'],['יחידת תחזוקה 08','הרובוט שמר עותק של הארכיון. לפני שנגמר החשמל, הוא סגר את חדר השירות כדי שהעכביש לא יגיע לזיכרון שלו.'],['המחקר שמתחת לבית','מאחורי כפתור סימן השאלה מסתתרת תחנת מחקר ישנה. משם הגיע החומר שהאיץ את הגדילה. הדוח האחרון מזהיר: אל תפתחו את פתחי הסלע.']];
export function recordImage(i){i=Math.max(0,Math.min(records.length-1,i));return '<div class="archive-photo" role="img" aria-label="'+records[i][0]+'" style="background-position:'+(i%3*50)+'% '+(Math.floor(i/3)*100)+'%"></div>';}
export function archiveHTML(index=0){return '<div class="archive-desktop"><p>ארכיון 08 · תמונות בדיוניות מהניסוי · לחץ לפתיחה</p><div class="archive-thumbnails">'+records.map(([title],i)=>'<button id="archive-thumb-'+i+'" aria-pressed="'+(i===index)+'">'+recordImage(i)+'<span>'+title+'</span></button>').join('')+'</div><figure class="archive-record">'+recordImage(index)+'<figcaption><strong>'+records[index][0]+'</strong><p>'+records[index][1]+'</p></figcaption></figure><nav class="archive-nav"><button id="archive-prev" class="outline">→ הקודמת</button><span aria-live="polite">'+(index+1)+' / '+records.length+'</span><button id="archive-next" class="outline">הבאה ←</button></nav></div>';}
export const ARCHIVE_HTML=archiveHTML();
export function openArchiveGallery(container,getElement=id=>document.getElementById(id)){let index=0;function render(){container.innerHTML=archiveHTML(index);for(let i=0;i<records.length;i++)getElement('archive-thumb-'+i).onclick=()=>{index=i;render();};getElement('archive-prev').onclick=()=>{index=(index+records.length-1)%records.length;render();};getElement('archive-next').onclick=()=>{index=(index+1)%records.length;render();};}render();return()=>index;}
export function buildArchiveDesk({THREE,scene,box,solid,glow,label,colliders,position={x:6,z:-36.5}}){const before=new Set(scene.children),firstCollider=colliders.length;const H=-4.2;label('מחשב הארכיון — E ליד הכיסא',6,H+2.1,-36.8,0,'#bed4b8',2.6);
 solid(2.4,.12,1.2,0x5b4e3c,6,H+.9,-36.5);for(const x of [5,7])for(const z of [-36.95,-36.05])box(.1,.88,.1,0x373d37,x,H+.44,z);
 box(.85,.055,.6,0x273337,6,H+1,-36.45);const screen=box(.88,.58,.045,0x1b2529,6,H+1.29,-36.72);screen.rotation.x=-.12;box(.75,.45,.02,0x365857,6,H+1.29,-36.68);for(let i=0;i<9;i++)box(.055,.012,.18,0x6a7772,5.66+i*.08,H+1.036,-36.43);label('ארכיון 08',6,H+1.3,-36.65,0,'#bed4b8',.65);glow(0x81b6ae,.8,4,6,H+1.5,-36);
 const mouse=new THREE.Mesh(new THREE.SphereGeometry(1,16,10),new THREE.MeshStandardMaterial({color:0x252d2d,roughness:.6}));mouse.name='Archive computer mouse';mouse.position.set(6.82,H+1.025,-36.4);mouse.scale.set(.10,.055,.16);scene.add(mouse);box(.014,.015,.05,0x88938b,6.82,H+1.08,-36.44);
 solid(.85,.6,.8,0x4b493d,6,H+.3,-35.2);box(.85,.9,.12,0x4b493d,6,H+.9,-34.85);const dx=position.x-6,dz=position.z+36.5;for(const object of scene.children)if(!before.has(object)){object.position.x+=dx;object.position.z+=dz;}for(const c of colliders.slice(firstCollider)){c.x+=dx;c.z+=dz;}return{x:position.x,y:H,z:-34.7+dz,seatZ:-35.3+dz,screenZ:-36.7+dz};}
